  if (preset !== "custom") return { preset, reasoningEffort: AI_PRESETS[preset].reasoningEffort, maxTokens: AI_PRESETS[preset].maxTokens };
  const reasoningEffort = AI_EFFORTS.indexOf(source.reasoningEffort) >= 0 ? source.reasoningEffort : DEFAULT_AI.reasoningEffort;
